suspend fun handle(req: Req, deadlineNanos: Long) {
    val remaining = (deadlineNanos - System.nanoTime()).nanoseconds
    if (remaining <= Duration.ZERO) throw DeadlineExceeded()
    withTimeout(remaining) {          // child coroutines inherit the cancellation
        callDownstream(req)           // suspending, or wrapped in runInterruptible
    }
}
